// AIE2PGenInstrInfo.td, copyright 2024-2026 Advanced Micro Devices, Inc.
//! Offline AIE2P exposed-pipeline checking; no vendor compiler/runtime required.
//!
//! One bundle issues per cycle. Operand cycles are one-based TableGen pipeline
//! stages; resources below use zero-based offsets. RAW/WAW require a strictly
//! earlier write, WAR allows reading in the write cycle. Matching MV/VEC bypass
//! classes forward one cycle early (including the converse WAR constraint).
//! Jump/call/return transfers take effect after **five bundles**, not five bytes.
//! `check_program` assumes declared logical issue order: each read wants the
//! latest issued definition, and memory operations are ordered with locks.
//! `check_decoded_program` instead checks physical conflicts. Machine code has
//! no dependency/version annotations: software-pipelined code deliberately
//! reads OLD values while a newer load is still in flight. Such reads, reordered
//! writes, and unannotated memory/lock order are `timing_observations`, not proven
//! hazards. Zero physical findings does NOT certify semantic RAW/WAR/WAW or
//! semaphore correctness. Memory alias `None` likewise remains unknown.
//! Conservative lock stall/resume stages are 2/8, as in AIEBaseInstrInfo.cpp.
//! Register accesses must use canonical, leaf register names: callers expand
//! super-registers and include implicit definitions/uses. Unknown opcodes or
//! operands are errors, not zero-latency instructions. `check_program` follows
//! direct control-flow edges, including backwards edges, within the maximum
//! exposed pipeline window. Indirect transfers terminate that path and are
//! counted in coverage. It does not prove semantic initialization or lock values.
//! Bundles are supplied in increasing PC order. Run the offline gates with
//! `cargo test -p peacemaker-npu sched_synthetic` and
//! `cargo test -p peacemaker-npu sched_vendor_core_elfs -- --nocapture`.
//! The vendor gate skips only if its corpus directory is absent; it checks all
//! decoded executable sections without opcode exclusions (NOP16 is inert).

use std::collections::BTreeSet;

pub const JUMP_DELAY_SLOTS: usize = 5;
pub const LOCK_STALL_CYCLE: i64 = 2;
pub const LOCK_RESUME_CYCLE: i64 = 8;
pub const DONE_RETIRE_CYCLE: u8 = 6;
// All operand/resource/memory cycles in the imported model fit in 11 cycles.
const HORIZON: usize = 11;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ResourceUse {
    pub resource: u8,
    pub start: u8,
    pub cycles: u8,
    /// Reserved vs Reserved does not conflict; either vs Required does.
    pub reserved: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct OperandTiming {
    pub name: &'static str,
    pub cycle: u8,
    /// 0 = none, 1 = MV, 2 = VEC.
    pub bypass: u8,
}

#[derive(Clone, Copy, Debug)]
pub struct Itinerary {
    pub class: &'static str,
    pub slots: u8,
    pub resources: &'static [ResourceUse],
    pub operands: &'static [OperandTiming],
    pub memory_cycles: &'static [u8],
    pub delay_slots: u8,
    pub load: bool,
    pub store: bool,
    pub lock: bool,
    pub stream: bool,
    pub done: bool,
}

impl Itinerary {
    /// Latest observable stage, including memory, stream status and lock request.
    pub fn retire_cycle(&self) -> u8 {
        self.operands.iter().map(|o| o.cycle)
            .chain(self.memory_cycles.iter().copied())
            .chain(self.resources.iter().map(|r| r.start + r.cycles))
            .chain(self.done.then_some(DONE_RETIRE_CYCLE)).max().unwrap_or(0)
    }

    pub fn operand_index(&self, name: &str, occurrence: usize) -> Option<usize> {
        self.operands.iter().enumerate().filter(|(_, o)| o.name == name)
            .nth(occurrence).map(|(i, _)| i)
    }
}

/// Look up either `II_ADD_add_r_ri` or `ADD_add_r_ri`.
pub fn itinerary(class: &str) -> Option<&'static Itinerary> {
    let class = class.strip_prefix("II_").unwrap_or(class);
    ITINERARIES.binary_search_by_key(&class, |i| i.class).ok().map(|i| &ITINERARIES[i])
}

#[derive(Clone, Copy, Debug)]
pub struct RegisterAccess<'a> {
    pub register: &'a str,
    pub operand: usize,
    pub write: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct MemoryAccess {
    /// Same key means aliasing; different keys are proved disjoint by the caller.
    pub alias: Option<u64>,
    pub write: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Flow {
    Next,
    Jump(u64),
    Conditional(u64),
    /// Callee edge only: the return address is not an immediate successor.
    Call(u64),
    Indirect,
    ConditionalIndirect,
    /// Zero-overhead LE -> LS edge: no jump delay window.
    Loop(u64),
    Done,
}

#[derive(Clone, Copy, Debug)]
pub struct SchedInst<'a> {
    pub itinerary: &'static Itinerary,
    pub registers: &'a [RegisterAccess<'a>],
    pub memory: Option<MemoryAccess>,
    pub flow: Flow,
}

#[derive(Clone, Copy, Debug)]
pub struct SchedBundle<'a> {
    pub pc: u64,
    pub instructions: &'a [SchedInst<'a>],
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum HazardKind {
    Raw, War, Waw, RegisterPort, Resource, Slot, MemoryOrder,
    LockRetire, LockResume, StreamRetire, DoneRetire, DelaySlot,
    InvalidTarget, InvalidOperand, InvalidFlow,
}

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct Hazard {
    pub kind: HazardKind,
    pub pc: u64,
    pub prior_pc: u64,
    pub detail: String,
}

#[derive(Clone, Debug, Default)]
pub struct Report {
    pub hazards: Vec<Hazard>,
    /// Potential semantic dependencies; no intent can be inferred from bytes.
    pub timing_observations: Vec<Hazard>,
    pub bundles: usize,
    pub instructions: usize,
    pub unknown_memory_aliases: usize,
    pub indirect_transfers: usize,
    pub zero_overhead_loops: usize,
}

impl Report {
    pub fn is_clean(&self) -> bool { self.hazards.is_empty() }
}

fn finding(out: &mut BTreeSet<Hazard>, kind: HazardKind, pc: u64, prior_pc: u64, detail: &str) {
    out.insert(Hazard { kind, pc, prior_pc, detail: detail.to_owned() });
}

fn forwarded(a: OperandTiming, b: OperandTiming) -> i64 {
    i64::from(a.bypass != 0 && a.bypass == b.bypass)
}

fn overlaps(a: ResourceUse, b: ResourceUse, distance: i64) -> bool {
    a.resource == b.resource && !(a.reserved && b.reserved)
        && i64::from(a.start) < distance + i64::from(b.start + b.cycles)
        && distance + i64::from(b.start) < i64::from(a.start + a.cycles)
}

fn check_pair(
    out: &mut BTreeSet<Hazard>, observations: &mut BTreeSet<Hazard>, strict: bool,
    source: SchedBundle<'_>, dest: SchedBundle<'_>, distance: i64, between: &[SchedBundle<'_>],
) {
    if distance >= 11 { return; }
    for (ai, a) in source.instructions.iter().enumerate() {
        for (bi, b) in dest.instructions.iter().enumerate() {
            if distance == 0 && ai >= bi { continue; }
            for &ra in a.itinerary.resources {
                for &rb in b.itinerary.resources {
                    if overlaps(ra, rb, distance) {
                        let name = RESOURCE_NAMES[usize::from(ra.resource)];
                        let kind = if name.contains("PORT") { HazardKind::RegisterPort }
                            else if a.itinerary.stream || b.itinerary.stream { HazardKind::StreamRetire }
                            else { HazardKind::Resource };
                        finding(out, kind, dest.pc, source.pc, name);
                    }
                }
            }
            for x in a.registers {
                let Some(&xt) = a.itinerary.operands.get(x.operand) else { continue; };
                for y in b.registers {
                    if x.register != y.register { continue; }
                    let Some(&yt) = b.itinerary.operands.get(y.operand) else { continue; };
                    let (kind, required) = match (x.write, y.write) {
                        (true, false) if distance != 0 => {
                            // The read depends on the latest issued writer, not every
                            // historical definition of this register.
                            if between.iter().flat_map(|p| p.instructions).any(|i|
                                i.registers.iter().any(|r| r.write && r.register == x.register)) {
                                continue;
                            }
                            (HazardKind::Raw, i64::from(xt.cycle) - i64::from(yt.cycle)
                                - forwarded(xt, yt) + 1)
                        }
                        (true, false) => (HazardKind::War,
                            i64::from(yt.cycle) - i64::from(xt.cycle) + forwarded(xt, yt)),
                        (false, true) => (HazardKind::War,
                            i64::from(xt.cycle) - i64::from(yt.cycle) + forwarded(yt, xt)),
                        (true, true) => (HazardKind::Waw, if distance == 0 { 1 } else {
                            i64::from(xt.cycle) - i64::from(yt.cycle) + 1
                        }),
                        _ => continue,
                    };
                    if distance < required {
                        let kind = if a.itinerary.stream && x.register.starts_with("sr") {
                            HazardKind::StreamRetire
                        } else { kind };
                        let simultaneous_write = x.write && y.write
                            && i64::from(xt.cycle) == distance + i64::from(yt.cycle);
                        let findings = if strict || simultaneous_write { &mut *out } else { &mut *observations };
                        finding(findings, kind, dest.pc, source.pc, x.register);
                    }
                }
            }
            if let (Some(am), Some(bm)) = (a.memory, b.memory) {
                if am.alias.is_some() && am.alias == bm.alias && (am.write || bm.write) {
                    if let (Some(&last), Some(&first)) =
                        (a.itinerary.memory_cycles.last(), b.itinerary.memory_cycles.first()) {
                        if distance < i64::from(last) - i64::from(first) + 1 {
                            finding(out, HazardKind::MemoryOrder, dest.pc, source.pc, "aliasing memory retire");
                        }
                    }
                }
            }
            let a_last = a.itinerary.memory_cycles.last().copied();
            let b_first = b.itinerary.memory_cycles.first().copied();
            if let Some(last) = a_last {
                if (b.itinerary.lock || b.itinerary.done)
                    && distance < i64::from(last) - LOCK_STALL_CYCLE + 1 {
                    let kind = if b.itinerary.lock { HazardKind::LockRetire } else { HazardKind::DoneRetire };
                    let findings = if strict || b.itinerary.done { &mut *out } else { &mut *observations };
                    finding(findings, kind, dest.pc, source.pc, "memory before stall");
                }
            }
            if a.itinerary.lock {
                if let Some(first) = b_first {
                    let required = if b.itinerary.class.contains("_TM_") { 1 }
                        else { LOCK_RESUME_CYCLE - i64::from(first) + 1 };
                    if distance < required {
                        let findings = if strict { &mut *out } else { &mut *observations };
                        finding(findings, HazardKind::LockResume, dest.pc, source.pc, "memory before resume");
                    }
                }
            }
            if b.itinerary.done && (a.itinerary.stream || a.itinerary.lock)
                && distance + i64::from(DONE_RETIRE_CYCLE) < i64::from(a.itinerary.retire_cycle()) {
                finding(out, HazardKind::DoneRetire, dest.pc, source.pc, "side effect after done");
            }
        }
    }
}

/// Check all exposed-pipeline hazards along direct CFG edges. Unknown memory
/// addresses and indirect targets are counted separately from actual findings.
/// Empty instruction slices are real one-cycle NOP bundles.
pub fn check_program(program: &[SchedBundle<'_>]) -> Report {
    check_program_mode(program, true, &[])
}

fn check_program_mode(program: &[SchedBundle<'_>], strict: bool, loop_edges: &[(usize, u64)]) -> Report {
    let mut out = BTreeSet::new();
    let mut observations = BTreeSet::new();
    let mut report = Report { bundles: program.len(), ..Report::default() };
    let mut legal_slots = [false; 256];
    for format in super::gen::FORMATS {
        let available = format.slots.iter().fold(0u8, |mask, s| mask | (1 << s.slot as u8));
        let mut subset = available;
        loop {
            legal_slots[usize::from(subset)] = true;
            if subset == 0 { break; }
            subset = (subset - 1) & available;
        }
    }
    let mut edges: Vec<[Option<usize>; 2]> = (0..program.len())
        .map(|i| [((i + 1) < program.len()).then_some(i + 1), None]).collect();
    for (index, bundle) in program.iter().enumerate() {
        let mut slots = 0;
        for inst in bundle.instructions {
            report.instructions += 1;
            if slots & inst.itinerary.slots != 0 {
                finding(&mut out, HazardKind::Slot, bundle.pc, bundle.pc, inst.itinerary.class);
            }
            slots |= inst.itinerary.slots;
            for access in inst.registers {
                if access.operand >= inst.itinerary.operands.len() {
                    finding(&mut out, HazardKind::InvalidOperand, bundle.pc, bundle.pc, access.register);
                }
            }
            if inst.memory.is_some_and(|m| m.alias.is_none()) { report.unknown_memory_aliases += 1; }
            if let Flow::Loop(pc) = inst.flow {
                report.zero_overhead_loops += 1;
                let target = program.binary_search_by_key(&pc, |b| b.pc).ok();
                if target.is_none() {
                    finding(&mut out, HazardKind::InvalidTarget, bundle.pc, bundle.pc, "loop target not a bundle boundary");
                }
                edges[index] = [target, ((index + 1) < program.len()).then_some(index + 1)];
                continue;
            }
            if inst.flow == Flow::Next {
                if inst.itinerary.delay_slots != 0 || inst.itinerary.done {
                    finding(&mut out, HazardKind::InvalidFlow, bundle.pc, bundle.pc, inst.itinerary.class);
                }
                continue;
            }
            if inst.flow == Flow::Done {
                if !inst.itinerary.done {
                    finding(&mut out, HazardKind::InvalidFlow, bundle.pc, bundle.pc, "non-DONE termination");
                }
                edges[index] = [None, None];
                continue;
            }
            if inst.itinerary.delay_slots != JUMP_DELAY_SLOTS as u8 {
                finding(&mut out, HazardKind::InvalidFlow, bundle.pc, bundle.pc, "non-jump transfer");
                continue;
            }
            let end = index + JUMP_DELAY_SLOTS;
            if end >= program.len() {
                finding(&mut out, HazardKind::DelaySlot, bundle.pc, bundle.pc, "missing five delay bundles");
                continue;
            }
            for delay in &program[index + 1..=end] {
                if delay.instructions.iter().any(|i| i.itinerary.delay_slots != 0 || i.itinerary.done) {
                    finding(&mut out, HazardKind::DelaySlot, delay.pc, bundle.pc, "control transfer in delay window");
                }
            }
            let target = match inst.flow {
                Flow::Jump(pc) | Flow::Conditional(pc) | Flow::Call(pc) => {
                    let target = program.binary_search_by_key(&pc, |b| b.pc).ok();
                    if target.is_none() {
                        finding(&mut out, HazardKind::InvalidTarget, bundle.pc, bundle.pc, "target not a bundle boundary");
                    }
                    target
                }
                Flow::Indirect | Flow::ConditionalIndirect => { report.indirect_transfers += 1; None }
                _ => unreachable!(),
            };
            edges[end] = if matches!(inst.flow, Flow::Conditional(_) | Flow::ConditionalIndirect) {
                [target, ((end + 1) < program.len()).then_some(end + 1)]
            } else { [target, None] };
        }
        if !legal_slots[usize::from(slots)] {
            finding(&mut out, HazardKind::Slot, bundle.pc, bundle.pc, "no legal VLIW format");
        }
        check_pair(&mut out, &mut observations, strict, *bundle, *bundle, 0, &[]);
    }
    for &(index, pc) in loop_edges {
        report.zero_overhead_loops += 1;
        let target = program.binary_search_by_key(&pc, |b| b.pc).ok();
        if target.is_none() {
            finding(&mut out, HazardKind::InvalidTarget, program[index].pc, program[index].pc,
                "loop target not a bundle boundary");
        }
        edges[index] = [target, ((index + 1) < program.len()).then_some(index + 1)];
    }
    // Pairwise bounded path walk needs no unbounded fixpoint even for loops:
    // every hazard in this model has a finite, <= HORIZON issue distance.
    for source in 0..program.len() {
        if program[source].instructions.iter().all(|i| i.itinerary.retire_cycle() == 0) { continue; }
        let mut path = [0usize; HORIZON];
        walk(program, &edges, source, source, 0, &mut path, &mut out, &mut observations, strict);
    }
    report.hazards = out.into_iter().collect();
    report.timing_observations = observations.into_iter().collect();
    report
}

fn walk(
    program: &[SchedBundle<'_>], edges: &[[Option<usize>; 2]], source: usize,
    current: usize, distance: usize, path: &mut [usize; HORIZON], out: &mut BTreeSet<Hazard>,
    observations: &mut BTreeSet<Hazard>, strict: bool,
) {
    if distance + 1 >= HORIZON { return; }
    for next in edges[current].into_iter().flatten() {
        let mut between = [SchedBundle { pc: 0, instructions: &[] }; HORIZON];
        for (dst, &idx) in between.iter_mut().zip(&path[..distance]) { *dst = program[idx]; }
        check_pair(out, observations, strict, program[source], program[next],
            (distance + 1) as i64, &between[..distance]);
        path[distance] = next;
        walk(program, edges, source, next, distance + 1, path, out, observations, strict);
    }
}

#[derive(Debug)]
pub struct ScheduleError(pub String);
impl std::fmt::Display for ScheduleError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { f.write_str(&self.0) }
}
impl std::error::Error for ScheduleError {}

/// Adapt the repository decoder, selecting register-specific itineraries,
/// expanding physical aliases, and restoring implicit defs/uses.
/// All DM addresses remain explicitly unknown: decoding alone does not prove
/// pointer values. Unknown indirect control targets are counted in the report.
pub fn check_decoded_program(program: &[super::decode::DecodedBundle]) -> Result<Report, ScheduleError> {
    struct Record {
        itinerary: &'static Itinerary,
        registers: std::ops::Range<usize>,
        memory: Option<MemoryAccess>,
        flow: Flow,
    }
    let mut registers = Vec::new();
    let mut records = Vec::new();
    let mut ranges = Vec::with_capacity(program.len());
    let (mut loop_start, mut loop_end) = (None, None);
    let mut loop_enabled = true;
    let mut loop_edges = Vec::new();
    for bundle in program {
        let begin = records.len();
        for decoded in &bundle.instructions {
            let opcode = decoded.encoding.name;
            // NOP16 is the sole architecturally inert NoItinerary instruction.
            if opcode == "NOP" && decoded.encoding.slot == super::gen::Slot::Nop16 { continue; }
            let info = opcode_info(opcode)
                .or_else(|| opcode_info(decoded.encoding.itinerary.strip_prefix("II_").unwrap_or("")))
                .ok_or_else(|| ScheduleError(format!("{:#x}: missing opcode itinerary {opcode}", bundle.pc)))?;
            let mut canonical = [None; 32];
            if decoded.operands.len() > canonical.len() {
                return Err(ScheduleError(format!("{opcode}: too many operands")));
            }
            for (i, (value, operand)) in decoded.operands.iter().zip(decoded.encoding.operands).enumerate() {
                if !operand.registers.is_empty() {
                    canonical[i] = Some(super::decode::resolve_register(operand, value.value as u64)
                        .ok_or_else(|| ScheduleError(format!("{:#x}: invalid {} register", bundle.pc, value.name)))?.name);
                }
            }
            let itinerary = info.select(&canonical[..decoded.operands.len()]);
            let literal = decoded.operands.iter().find(|o| matches!(o.name, "i" | "imm")).map(|o| o.value as u64);
            for (i, _) in decoded.operands.iter().enumerate().filter(|(_, o)| o.output) {
                match canonical[i] {
                    Some("ls") => loop_start = literal,
                    Some("le") => loop_end = literal,
                    Some("lc") => loop_enabled = literal != Some(0),
                    _ => {}
                }
                // Arithmetic immediates still depend on an input register.
                if !matches!(opcode, "MOVXM" | "MOVX_alu_cg" | "MOV_alu_mv_mv_mv_cg" | "MOVA") {
                    match canonical[i] {
                        Some("ls") => loop_start = None,
                        Some("le") => loop_end = None,
                        _ => {}
                    }
                }
            }
            let start = registers.len();
            for (i, value) in decoded.operands.iter().enumerate() {
                if let Some(register) = canonical[i] {
                    if i >= itinerary.operands.len() {
                        return Err(ScheduleError(format!("{opcode}: missing timing for {}", value.name)));
                    }
                    add_register(&mut registers, register, i, value.output);
                }
            }
            for implicit in info.implicit {
                if implicit.operand >= itinerary.operands.len() {
                    return Err(ScheduleError(format!("{opcode}: missing implicit timing for {}", implicit.register)));
                }
                add_register(&mut registers, implicit.register, implicit.operand, implicit.write);
            }
            let immediate_target = decoded.operands.iter().find(|o| o.kind == "cpmaddr").map(|o| o.value as u64);
            let flow = if itinerary.done { Flow::Done }
                else if itinerary.delay_slots == 0 { Flow::Next }
                else if opcode.starts_with("JL_") {
                    immediate_target.map_or(Flow::Indirect, Flow::Call)
                } else if matches!(opcode, "JNZ" | "JZ" | "JNZD") {
                    immediate_target.map_or(Flow::ConditionalIndirect, Flow::Conditional)
                } else { immediate_target.map_or(Flow::Indirect, Flow::Jump) };
            records.push(Record {
                itinerary,
                registers: start..registers.len(),
                memory: (!itinerary.memory_cycles.is_empty()).then_some(MemoryAccess {
                    alias: None, write: itinerary.store,
                }),
                flow,
            });
        }
        if loop_enabled && loop_end == Some(bundle.pc) {
            if let Some(target) = loop_start {
                loop_edges.push((ranges.len(), target));
            }
        }
        ranges.push(begin..records.len());
    }
    let instructions: Vec<_> = records.iter().map(|r| SchedInst {
        itinerary: r.itinerary, registers: &registers[r.registers.clone()], memory: r.memory, flow: r.flow,
    }).collect();
    let bundles: Vec<_> = program.iter().zip(ranges).map(|(b, range)| SchedBundle {
        pc: b.pc, instructions: &instructions[range],
    }).collect();
    Ok(check_program_mode(&bundles, false, &loop_edges))
}

fn add_register(out: &mut Vec<RegisterAccess<'static>>, register: &'static str, operand: usize, write: bool) {
    if let Some(leaves) = register_leaves(register) {
        out.extend(leaves.iter().map(|&register| RegisterAccess { register, operand, write }));
    } else { out.push(RegisterAccess { register, operand, write }); }
}

/// Physical leaf aliases, derived from AIE2PRegisterInfo.td SubRegs.
/// A leaf register itself returns None.
pub fn register_leaves(register: &str) -> Option<&'static [&'static str]> {
    REGISTER_ALIASES.binary_search_by_key(&register, |r| r.0).ok().map(|i| REGISTER_ALIASES[i].1)
}

