#[derive(Clone, Copy, Debug)]
pub struct ImplicitAccess {
    pub register: &'static str,
    pub operand: usize,
    pub write: bool,
}
#[derive(Clone, Copy, Debug)]
pub struct RegCondition {
    pub operand: usize,
    pub members: &'static [&'static str],
}
#[derive(Clone, Copy, Debug)]
pub struct Refinement {
    pub class: &'static str,
    pub conditions: &'static [RegCondition],
}
#[derive(Clone, Copy, Debug)]
pub struct OpcodeInfo {
    pub opcode: &'static str,
    pub class: &'static str,
    pub implicit: &'static [ImplicitAccess],
    pub refinements: &'static [Refinement],
}
pub fn opcode_info(opcode: &str) -> Option<&'static OpcodeInfo> {
    OPCODES.binary_search_by_key(&opcode, |i| i.opcode).ok().map(|i| &OPCODES[i])
}
impl OpcodeInfo {
    /// Registers in decoder operand order, including None for immediates.
    /// Member tables use LLVM canonical internal register identifiers.
    pub fn select(&self, registers: &[Option<&str>]) -> &'static Itinerary {
        for refinement in self.refinements {
            if refinement.conditions.iter().all(|c| registers.get(c.operand)
                .and_then(|r| *r).is_some_and(|r| c.members.contains(&r))) {
                return itinerary(refinement.class).expect("generated refinement exists");
            }
        }
        itinerary(self.class).expect("generated opcode itinerary exists")
    }
}
