#[cfg(test)]
mod tests {
    use super::*;

    struct TestInst {
        itinerary: &'static Itinerary,
        registers: Vec<RegisterAccess<'static>>,
        memory: Option<MemoryAccess>,
        flow: Flow,
    }

    fn inst(class: &str, regs: &[(&'static str, &'static str, bool)]) -> TestInst {
        let itinerary = itinerary(class).unwrap();
        TestInst {
            itinerary,
            registers: regs.iter().map(|&(register, name, write)| RegisterAccess {
                register, operand: itinerary.operand_index(name, 0).unwrap(), write,
            }).collect(),
            memory: None,
            flow: Flow::Next,
        }
    }

    fn transfer(class: &str, flow: Flow) -> TestInst {
        let mut i = inst(class, &[]);
        i.flow = flow;
        i
    }

    fn mem(class: &str, alias: Option<u64>, write: bool) -> TestInst {
        let mut i = inst(class, &[]);
        i.memory = Some(MemoryAccess { alias, write });
        i
    }

    fn run(spec: Vec<Vec<TestInst>>) -> Report {
        let instructions: Vec<Vec<_>> = spec.iter().map(|bundle| bundle.iter().map(|i| SchedInst {
            itinerary: i.itinerary, registers: &i.registers, memory: i.memory, flow: i.flow,
        }).collect()).collect();
        let program: Vec<_> = instructions.iter().enumerate().map(|(i, instructions)| SchedBundle {
            pc: i as u64 * 16, instructions,
        }).collect();
        check_program(&program)
    }

    fn spaced(a: TestInst, b: TestInst, distance: usize) -> Report {
        let mut p = vec![vec![a]];
        p.extend((1..distance).map(|_| vec![]));
        p.push(vec![b]);
        run(p)
    }

    fn has(r: &Report, kind: HazardKind) {
        assert!(r.hazards.iter().any(|h| h.kind == kind), "missing {kind:?}: {:?}", r.hazards);
    }

    #[test]
    fn sched_synthetic_register_hazards() {
        for distance in [1, 5] {
            has(&spaced(
                inst("MOV_d5", &[("r0", "dst", true)]),
                inst("ADD_add_r_ri", &[("r0", "s0", false)]), distance), HazardKind::Raw);
        }
        assert!(spaced(
            inst("MOV_d5", &[("r0", "dst", true)]),
            inst("ADD_add_r_ri", &[("r0", "s0", false)]), 6).is_clean());
        has(&spaced(
            inst("ST_s8_idx_imm", &[("r0", "src", false)]),
            inst("MOVXM_eR", &[("r0", "dst", true)]), 1), HazardKind::War);
        assert!(spaced(
            inst("ST_s8_idx_imm", &[("r0", "src", false)]),
            inst("MOVXM_eR", &[("r0", "dst", true)]), 6).is_clean());
        has(&spaced(
            inst("LDA_dms_lda_idx_imm_eR", &[("r0", "dst", true)]),
            inst("MOVXM_eR", &[("r0", "dst", true)]), 1), HazardKind::Waw);
        assert!(spaced(
            inst("LDA_dms_lda_idx_imm_eR", &[("r0", "dst", true)]),
            inst("MOVXM_eR", &[("r0", "dst", true)]), 7).is_clean());
        // A superseding writer kills an older RAW dependency.
        let r = run(vec![
            vec![inst("MOV_d5", &[("r0", "dst", true)])],
            vec![inst("MOVXM_eR", &[("r0", "dst", true)])],
            vec![inst("ADD_add_r_ri", &[("r0", "s0", false)])],
        ]);
        assert!(!r.hazards.iter().any(|h| h.kind == HazardKind::Raw && h.pc == 32));
    }

    #[test]
    fn sched_synthetic_bypass() {
        // Both operands forward: E2 producer -> E1 consumer is legal at +1.
        let a = "MOV_alu_mv_mv_mv_e_mv_eh_to_eh";
        let b = "MOV_alu_mv_mv_mv_e_mv_eh_to_el";
        assert!(spaced(inst(a, &[("eh0", "dst", true)]),
            inst(b, &[("eh0", "src", false)]), 1).is_clean());
        // An ordinary reader has no bypass, so it must issue at +2.
        has(&spaced(inst(a, &[("eh0", "dst", true)]),
            inst("MOV_alu_mv_mv_mv_scl", &[("eh0", "src", false)]), 1), HazardKind::Raw);
    }

    #[test]
    fn sched_synthetic_slot_and_port_hazards() {
        has(&run(vec![vec![inst("ADD_add_r_ri", &[]), inst("ACQ_mLockId_imm", &[])]]), HazardKind::Slot);
        has(&run(vec![vec![inst("MOVA_eP", &[]), inst("MOVXM_eP", &[])]]), HazardKind::RegisterPort);
        assert!(run(vec![vec![inst("MOVA_eP", &[]), inst("MOVXM_eR", &[])]]).is_clean());
        has(&spaced(inst("ACQ_mLockId_imm", &[]), inst("REL_mLockId_imm", &[]), 3), HazardKind::Resource);
        assert!(spaced(inst("ACQ_mLockId_imm", &[]), inst("REL_mLockId_imm", &[]), 4).is_clean());
        // Reserved PART_WORD_STORE uses may overlap each other.
        assert!(spaced(inst("LDA_dms_lda_idx_imm_eR", &[]),
            inst("LDA_dms_lda_idx_imm_eR", &[]), 1).is_clean());
        // A required seven-cycle partword reservation blocks a following load.
        has(&spaced(inst("ST_s8_idx_imm", &[]),
            inst("LDA_dms_lda_idx_imm_eR", &[]), 6), HazardKind::Resource);
        assert!(spaced(inst("ST_s8_idx_imm", &[]),
            inst("LDA_dms_lda_idx_imm_eR", &[]), 7).is_clean());
        has(&run(vec![vec![
            inst("ST_s8_idx_imm", &[("r0", "src", false)]),
            inst("MOVXM_eR", &[("r0", "dst", true)]),
        ]]), HazardKind::War);
        has(&run(vec![vec![
            transfer("J_lng", Flow::Jump(0)),
            inst("ADD_add_r_ri", &[]),
        ]]), HazardKind::Slot);
    }

    #[test]
    fn sched_synthetic_memory_and_lock_hazards() {
        has(&spaced(mem("ST_s8_idx_imm", Some(1), true),
            mem("LDA_dms_lda_idx_imm_eR", Some(1), false), 6), HazardKind::MemoryOrder);
        assert!(spaced(mem("ST_s8_idx_imm", Some(1), true),
            mem("LDA_dms_lda_idx_imm_eR", Some(1), false), 7).is_clean());
        has(&spaced(mem("ST_dms_sts_idx_imm_eR", Some(1), true),
            inst("REL_mLockId_imm", &[]), 3), HazardKind::LockRetire);
        assert!(spaced(mem("ST_dms_sts_idx_imm_eR", Some(1), true),
            inst("REL_mLockId_imm", &[]), 4).is_clean());
        has(&spaced(inst("ACQ_mLockId_imm", &[]),
            mem("LDA_dms_lda_idx_imm_eR", Some(1), false), 3), HazardKind::LockResume);
        assert!(spaced(inst("ACQ_mLockId_imm", &[]),
            mem("LDA_dms_lda_idx_imm_eR", Some(1), false), 4).is_clean());
        let unknown = spaced(mem("ST_dms_sts_idx_imm_eR", None, true),
            mem("LDA_dms_lda_idx_imm_eR", None, false), 1);
        assert_eq!(unknown.unknown_memory_aliases, 2);
        assert!(unknown.is_clean());
    }

    #[test]
    fn sched_synthetic_stream_and_done_retire() {
        has(&spaced(
            inst("MOV_st_mMStream_tlast_imm_eR", &[("srMS0", "srMS0", true)]),
            inst("MOV_alu_mv_mv_mv_scl", &[("srMS0", "src", false)]), 1), HazardKind::StreamRetire);
        assert!(spaced(
            inst("MOV_st_mMStream_tlast_imm_eR", &[("srMS0", "srMS0", true)]),
            inst("MOV_alu_mv_mv_mv_scl", &[("srMS0", "src", false)]), 3).is_clean());
        has(&spaced(mem("ST_dms_sts_idx_imm_eR", Some(1), true),
            transfer("DONE", Flow::Done), 3), HazardKind::DoneRetire);
        assert!(spaced(mem("ST_dms_sts_idx_imm_eR", Some(1), true),
            transfer("DONE", Flow::Done), 4).is_clean());
        has(&spaced(inst("VMOV_lda_mv_scd_x", &[]),
            inst("VADDMAC_vmac_cm2_add_scd_vmul_cm_core_X_X", &[]), 3), HazardKind::StreamRetire);
        assert!(spaced(inst("VMOV_lda_mv_scd_x", &[]),
            inst("VADDMAC_vmac_cm2_add_scd_vmul_cm_core_X_X", &[]), 4).is_clean());
        has(&run(vec![vec![inst("VMOV_lda_mv_scd_x", &[]),
            transfer("DONE", Flow::Done)]]), HazardKind::DoneRetire);
        assert_eq!(itinerary("DONE").unwrap().retire_cycle(), 6);
        assert_eq!(itinerary("ACQ_mLockId_imm").unwrap().retire_cycle(), 4);
        assert_eq!(itinerary("ST_s8_idx_imm").unwrap().retire_cycle(), 11);
    }

    #[test]
    fn sched_synthetic_delay_and_cfg_hazards() {
        has(&run(vec![vec![transfer("J_lng", Flow::Jump(0))]]), HazardKind::DelaySlot);
        let mut p = vec![vec![transfer("J_lng", Flow::Jump(0))]];
        p.extend((0..5).map(|_| vec![]));
        assert!(run(p).is_clean());
        let mut p = vec![vec![transfer("J_lng", Flow::Jump(7))]];
        p.extend((0..5).map(|_| vec![]));
        has(&run(p), HazardKind::InvalidTarget);
        let mut p = vec![vec![transfer("J_lng", Flow::Jump(0))],
            vec![transfer("RET", Flow::Indirect)]];
        p.extend((0..5).map(|_| vec![]));
        has(&run(p), HazardKind::DelaySlot);
        // Producer in the last delay bundle must be visible to a backedge consumer.
        let r = run(vec![
            vec![inst("ADD_add_r_ri", &[("r0", "s0", false)])],
            vec![transfer("J_lng", Flow::Jump(0))], vec![], vec![], vec![], vec![],
            vec![inst("LDA_dms_lda_idx_imm_eR", &[("r0", "dst", true)])],
        ]);
        assert!(r.hazards.iter().any(|h| h.kind == HazardKind::Raw && h.pc == 0 && h.prior_pc == 96));
        // Unconditional transfer does not also execute the physical fallthrough.
        let r = run(vec![
            vec![transfer("J_lng", Flow::Jump(0))], vec![], vec![], vec![], vec![],
            vec![inst("MOV_d5", &[("r0", "dst", true)])],
            vec![inst("ADD_add_r_ri", &[("r0", "s0", false)])],
        ]);
        assert!(!r.hazards.iter().any(|h| h.kind == HazardKind::Raw && h.pc == 96));
    }

    #[test]
    fn sched_synthetic_invalid_contracts() {
        let mut bad = inst("ADD_add_r_ri", &[]);
        bad.registers.push(RegisterAccess { register: "r0", operand: 99, write: true });
        has(&run(vec![vec![bad]]), HazardKind::InvalidOperand);
        has(&run(vec![vec![inst("J_lng", &[])]]), HazardKind::InvalidFlow);
        assert!(itinerary("NOT_AN_OPCODE").is_none());
        assert_eq!(opcode_info("MOVXM").unwrap().select(&[Some("p0"), None]).class, "MOVXM_eP");
        assert_eq!(opcode_info("MOVXM").unwrap().select(&[Some("r0"), None]).class, "MOVXM_eR");
    }

    fn decoded_image(bytes: &[u8]) -> Vec<super::super::decode::DecodedBundle> {
        let mut result = Vec::new();
        let mut offset = 0;
        while offset < bytes.len() {
            let bundle = super::super::decode::decode(&bytes[offset..], offset as u64).unwrap();
            offset += bundle.len;
            result.push(bundle);
        }
        result
    }

    #[test]
    fn sched_synthetic_physical_old_values_and_write_collision() {
        use super::super::{lda_idx_imm, movxm, Program, Reg, Inst};
        let mut p = Program::new();
        p.push(lda_idx_imm(Reg::R(7), Reg::P(0), 0));
        // OR alias with identical inputs must retain the canonical OR itinerary.
        p.push(Inst::Alu((7 << 15) | (7 << 5) | 0b1011));
        let report = check_decoded_program(&decoded_image(&p.bytes)).unwrap();
        assert!(report.is_clean());
        assert!(report.timing_observations.iter().any(|h| h.kind == HazardKind::Raw && h.detail == "r7"));
        // A later writer landing in the same physical register/cycle is always
        // a conflict, regardless of the intended logical dependency graph.
        let mut p = Program::new();
        p.push(lda_idx_imm(Reg::R(7), Reg::P(0), 0)).nops(5).push(movxm(Reg::R(7), 1));
        has(&check_decoded_program(&decoded_image(&p.bytes)).unwrap(), HazardKind::Waw);
        let mut p = Program::new();
        p.push(lda_idx_imm(Reg::R(7), Reg::P(0), 0)).nops(6).push(movxm(Reg::R(7), 1));
        assert!(check_decoded_program(&decoded_image(&p.bytes)).unwrap().is_clean());
    }

    #[test]
    fn sched_synthetic_zero_overhead_nop_loop() {
        use super::super::{Program, Inst};
        // The legacy Reg enum has no LS/LE/LC, so use resolved TableGen fields.
        let mut p = Program::new();
        let ls = super::super::gen::ENCODINGS.iter().find(|e| e.name == "MOVXM").unwrap();
        let make = |register: &str, value: u64| {
            let index = ls.operands[0].registers.iter().find(|r| r.name == register).unwrap().value;
            let payload = ls.fields.iter().fold(ls.value, |bits, f| {
                let v = if f.name == "dst" { index } else { value };
                bits | (((v >> f.source_lsb) & ((1u64 << f.width) - 1)) << f.lsb)
            });
            Inst::Lng(payload)
        };
        p.push(make("ls", 18)).push(make("le", 20)).push(make("lc", 1)).nops(2);
        let report = check_decoded_program(&decoded_image(&p.bytes)).unwrap();
        assert!(report.is_clean(), "{:?}", report.hazards);
        assert_eq!(report.zero_overhead_loops, 1);
    }

    #[test]
    fn sched_synthetic_superregister_collision() {
        let a = inst("VLDA_dmx_lda_bm_idx_imm", &[("bmll0", "dst", true)]);
        let mut b = inst("VMAC_vmul_cm_core_X_X", &[]);
        add_register(&mut b.registers, "dm0", 0, true);
        let report = spaced(a, b, 1);
        assert!(report.hazards.iter().any(|h| h.kind == HazardKind::Waw && h.detail == "bmll0"));
    }
}

