#[cfg(test)]
mod corpus_tests {
    use super::*;
    use std::path::{Path, PathBuf};

    fn cores(dir: &Path, files: &mut Vec<PathBuf>) {
        for entry in std::fs::read_dir(dir).unwrap() {
            let path = entry.unwrap().path();
            if path.is_dir() { cores(&path, files); }
            else if path.extension().is_some_and(|e| e == "elf") { files.push(path); }
        }
    }

    #[test]
    fn sched_vendor_core_elfs() {
        let Some(root) = crate::vendor_corpus().map(|r| r.join("cache")) else { return };
        let mut files = Vec::new();
        cores(&root, &mut files);
        files.sort();
        assert!(!files.is_empty(), "present vendor corpus contains no core ELFs");
        let mut counts = std::collections::BTreeMap::new();
        let (mut bundles, mut instructions, mut aliases, mut indirect, mut errors) = (0, 0, 0, 0, 0);
        let mut examples = Vec::new();
        let mut observations = std::collections::BTreeMap::new();
        let mut loops = 0;
        for path in &files {
            let data = std::fs::read(path).unwrap();
            for section in super::super::decode::executable_sections(&data).unwrap() {
                let mut decoded = Vec::new();
                let mut offset = 0;
                while offset < section.bytes.len() {
                    let bundle = super::super::decode::decode(&section.bytes[offset..], section.address + offset as u64)
                        .unwrap_or_else(|e| panic!("{}: {e}", path.display()));
                    offset += bundle.len;
                    decoded.push(bundle);
                }
                match check_decoded_program(&decoded) {
                    Ok(report) => {
                        bundles += report.bundles;
                        instructions += report.instructions;
                        aliases += report.unknown_memory_aliases;
                        indirect += report.indirect_transfers;
                        loops += report.zero_overhead_loops;
                        for observation in report.timing_observations {
                            *observations.entry(observation.kind).or_insert(0usize) += 1;
                        }
                        for hazard in report.hazards {
                            *counts.entry(hazard.kind).or_insert(0usize) += 1;
                            if examples.len() < 30 { examples.push(format!("{}: {hazard:?}", path.display())); }
                        }
                    }
                    Err(e) => {
                        errors += 1;
                        eprintln!("ADAPTATION {}: {e}", path.display());
                        if examples.len() < 30 { examples.push(format!("{}: {e}", path.display())); }
                    }
                }
            }
        }
        eprintln!("sched: {} core ELFs; {bundles} bundles; {instructions} non-NOP16 slot instructions; \
            {aliases} unknown memory aliases; {indirect} indirect transfers; {loops} zero-overhead loops; \
            {errors} adaptation errors; hazards={counts:?}; unproven timing observations={observations:?}",
            files.len());
        for example in examples { eprintln!("{example}"); }
        assert_eq!(errors, 0, "every decoded instruction must have scheduling metadata");
        assert!(counts.is_empty(), "vendor ELF scheduling findings: {counts:?}");
    }
}
